// Saca el PDF adjunto de cada correo y lo deja en base64.
// getBinaryDataBuffer funciona tanto si n8n guarda el fichero en memoria
// como en disco (leer .binary[clave].data a pelo solo vale en memoria).
const salida = [];
const entradas = $input.all();

for (let i = 0; i < entradas.length; i++) {
  const item = entradas[i];
  const bin = item.binary || {};
  const claves = Object.keys(bin);
  if (claves.length === 0) continue;

  const clave =
    claves.find(k => (bin[k].fileName || '').toLowerCase().endsWith('.pdf')) ||
    claves.find(k => (bin[k].mimeType || '').includes('pdf')) ||
    claves[0];

  const buffer = await this.helpers.getBinaryDataBuffer(i, clave);

  salida.push({
    json: {
      // El Gmail Trigger sin Simplify devuelve 'from' como OBJETO
      // ({value:[{address,name}], text, html}), no como texto. Firestore solo
      // admite texto en stringValue, asi que hay que quedarse con el texto.
      remitente: item.json.from?.text || item.json.from?.value?.[0]?.address || item.json.from || '',
      asunto: item.json.subject || item.json.Subject || '',
      fecha: item.json.date || item.json.Date || '',
      archivo: bin[clave].fileName || 'factura.pdf',
      pdf_base64: buffer.toString('base64'),
    },
  });
}

return salida;
